#include "v42_lapm.h"
#include <string.h>

static uint8_t address(unsigned cr){return(uint8_t)(1u|((cr&1u)<<1));}
size_t v42_lapm_encode_i(unsigned cr,unsigned ns,unsigned nr,unsigned p,const uint8_t*info,size_t n,uint8_t*bits,size_t cap){if(n>V42_HDLC_MAX_INFO)return 0;uint8_t raw[V42_HDLC_MAX_INFO+3]={address(cr),(uint8_t)((ns&127)<<1),(uint8_t)(((nr&127)<<1)|(p&1))};if(n)memcpy(raw+3,info,n);return v42_hdlc_encode_raw(raw,n+3,bits,cap);}
size_t v42_lapm_encode_s(enum v42_lapm_type t,unsigned cr,unsigned nr,unsigned pf,uint8_t*bits,size_t cap){static const uint8_t code[]={0,1,5,9,13};if(t<V42_LAPM_RR||t>V42_LAPM_SREJ)return 0;if(t==V42_LAPM_SREJ)pf=0;uint8_t raw[3]={address(cr),code[t],(uint8_t)(((nr&127)<<1)|(pf&1))};return v42_hdlc_encode_raw(raw,3,bits,cap);}
size_t v42_lapm_encode_u(enum v42_lapm_u t,unsigned cr,unsigned pf,const uint8_t*info,size_t n,uint8_t*bits,size_t cap){if(n>V42_HDLC_MAX_INFO)return 0;uint8_t raw[V42_HDLC_MAX_INFO+2]={address(cr),(uint8_t)(t|(pf?0x10:0))};if(n)memcpy(raw+2,info,n);return v42_hdlc_encode_raw(raw,n+2,bits,cap);}
int v42_lapm_decode(const uint8_t*bits,size_t n,struct v42_lapm_frame*f){uint8_t raw[V42_HDLC_MAX_INFO+3];int z=v42_hdlc_decode_raw(bits,n,raw,sizeof raw);if(z<2||!f)return-1;memset(f,0,sizeof*f);if(!(raw[0]&1))return-1;f->cr=(raw[0]>>1)&1;f->dlci=raw[0]>>2;if((raw[1]&1)==0){if(z<3)return-1;f->type=V42_LAPM_I;f->ns=raw[1]>>1;f->nr=raw[2]>>1;f->pf=raw[2]&1;f->info_count=(size_t)z-3;if(f->info_count)memcpy(f->info,raw+3,f->info_count);return 0;}if((raw[1]&3)==1){if(z!=3)return-1;switch(raw[1]){case 1:f->type=V42_LAPM_RR;break;case 5:f->type=V42_LAPM_RNR;break;case 9:f->type=V42_LAPM_REJ;break;case 13:f->type=V42_LAPM_SREJ;break;default:return-1;}f->nr=raw[2]>>1;f->pf=raw[2]&1;if(f->type==V42_LAPM_SREJ&&f->pf)return-1;return 0;}f->type=V42_LAPM_U;f->pf=(raw[1]>>4)&1;f->u_control=raw[1]&0xef;f->info_count=(size_t)z-2;if(f->info_count)memcpy(f->info,raw+2,f->info_count);return 0;}
